package com.foxnks.dockshift.data.db.entity

import androidx.room3.Entity
import androidx.room3.PrimaryKey

/**
 * Row of the `leaves` table: one planned annual leave.
 *
 * @property id identity, generated by the database.
 * @property startDate ISO date of the first day ("2026-12-21").
 * @property endDate ISO date of the last day; ISO text compares in calendar order.
 * @property note the user's name for the leave, or null.
 */
@Entity(tableName = "leaves")
data class LeaveEntity(
    @PrimaryKey(autoGenerate = true) val id: Long,
    val startDate: String,
    val endDate: String,
    val note: String?,
)
